 const cap=[[1.31,9.335,-2.58],[2.29,9.335,-2.58],[2.29,9.335,-1.62],[1.31,9.335,-1.62]],peak=[1.8,9.54,-2.1];
 for(let j=0;j<4;j++)tri('tile2',cap[(j+1)%4],cap[j],peak);""")
